package com.dshgo.shellpol;
import de.robv.android.xposed.XC_MethodHook;import de.robv.android.xposed.XposedBridge;import org.luckypray.dexkit.DexKitBridge;import org.luckypray.dexkit.query.FindMethod;import org.luckypray.dexkit.query.matchers.MethodMatcher;import org.luckypray.dexkit.result.MethodData;import java.lang.reflect.Method;import java.util.ArrayList;import java.util.Arrays;import java.util.List;
/** Application-process validators only; does not change remote host limits or identity checks. */
final class ShellProtocolRelax{private ShellProtocolRelax(){}static void install(DexKitBridge b,ClassLoader l)throws Exception{List<MethodData>cs=shaped(b,"invalidCommand","java.lang.String"),ts=shaped(b,"invalidTimeout","long");MethodData c=null,t=null;int pairs=0;for(MethodData x:cs)for(MethodData y:ts)if(x.getDeclaredClass().getName().equals(y.getDeclaredClass().getName())){c=x;t=y;pairs++;}XposedBridge.log(HookEntry.TAG+": protocol_candidates command="+cs.size()+" timeout="+ts.size()+" shared_owner_pairs="+pairs);if(pairs!=1)throw new IllegalStateException("protocol shared-owner pair count="+pairs);Method cm=c.getMethodInstance(l),tm=t.getMethodInstance(l);XC_MethodHook.Unhook ch=XposedBridge.hookMethod(cm,new XC_MethodHook(){@Override protected void beforeHookedMethod(MethodHookParam p){p.setResult(ShellRequestPolicy.commandError((String)p.args[0]));}});try{XposedBridge.hookMethod(tm,new XC_MethodHook(){@Override protected void beforeHookedMethod(MethodHookParam p){p.setResult(ShellRequestPolicy.timeoutError((Long)p.args[0]));}});}catch(Throwable f){ch.unhook();if(f instanceof Error)throw(Error)f;if(f instanceof Exception)throw(Exception)f;throw new IllegalStateException(f);}XposedBridge.log(HookEntry.TAG+": protocol_validators installed command="+c.getDescriptor()+" timeout="+t.getDescriptor());}private static List<MethodData> shaped(DexKitBridge b,String a,String p){List<MethodData>r=new ArrayList<>();for(MethodData m:b.findMethod(new FindMethod().matcher(new MethodMatcher().usingEqStrings(a))))if("java.lang.String".equals(m.getReturnTypeName())&&Arrays.asList(p).equals(m.getParamTypeNames()))r.add(m);return r;}}
